DROP TABLE IF EXISTS ld_stock;
CREATE TABLE ld_stock (product text PRIMARY KEY, qty integer NOT NULL);
INSERT INTO ld_stock VALUES ('pen', 10), ('book', 5);
INSERT INTO ld_stock (product, qty) VALUES ('book', 7), ('lamp', 3)
ON CONFLICT (product) DO UPDATE SET qty = EXCLUDED.qty;
SELECT product, qty FROM ld_stock ORDER BY product;
